recover
from patient


        and patient_id = #{patientId}


        and doctor_id = #{doctorId}


        and patient_name = #{patientName}


        and source = #{source}


        and patient_sex = #{patientSex}


        and patient_age = #{patientAge}


        and patient_group = #{patientGroup}


        and patient_work = #{patientWork}


        and patient_edu_level = #{patientEduLevel}


        and patient_marriage = #{patientMarriage}


        and patient_pregnancy = #{patientPregnancy}


        and patient_address = #{patientAddress}


        and patient_phone = #{patientPhone}


        and patient_malignant = #{patientMalignant}


        and patient_allergy = #{patientAllergy}


        and drug_name = #{drugName}


        and is_smoke = #{isSmoke}


        and smoking_type = #{smokingType}


        and smoking_years = #{smokingYears}


        and smoking_amount = #{smokingAmount}


        and is_quit = #{isQuit}


        and quit_years = #{quitYears}


        and medical_history = #{medicalHistory}


        and is_ recover = #{is_ recover}


limit #{pageable.offset}, #{pageable.pageSize}

select pt.patient_id, t.tag_name, r.next_time, r.result, r.representation, r.image, p.patient_name
from patient_tags as pt,
     reports as r,
     tags as t,
     patient as p
where r.patient_id = pt.patient_id
  and t.tag_id = pt.tag_id
  and p.patient_id = pt.patient_id
  and p.doctor_id = #{doctorId}
ORDER BY r.next_time ASC;

select pt.patient_id, t.tag_name, r.next_time, r.result, r.representation, r.image, p.patient_name
from patient_tags as pt,
     reports as r,
     tags as t,
     patient as p
where r.patient_id = pt.patient_id
  and t.tag_id = pt.tag_id
  and p.patient_id = pt.patient_id
  and p.doctor_id = #{doctorId}
ORDER BY r.next_time DESC;

select pt.patient_id, t.tag_name, r.next_time, r.result, r.representation, r.image, p.patient_name
from patient_tags as pt,
     reports as r,
     tags as t,
     patient as p
where r.patient_id = pt.patient_id
  and t.tag_id = pt.tag_id
  and p.patient_id = pt.patient_id
    LIMIT #{offset}
    , #{limit};

